  const b = f.properties.bbox;
  if (x < b[0] || x > b[2] || y < b[1] || y > b[3]) return false;
  const g = f.geometry;
  return g.type === 'Polygon' ? inPoly(x, y, g.coordinates) : g.coordinates.some(p => inPoly(x, y, p));
