for (const v of ['pol', 'pf']) for (const f of D[v].features) distIdx[v][f.properties.key] = f;
const regIdx = { pol: {}, pf: {} };
D.regPol.features.forEach(f => regIdx.pol[f.properties.key] = f);
D.regPf.features.forEach(f => regIdx.pf[f.properties.key] = f);
