    L.push({ id: 'bm-raster', type: 'raster', source: 'bm', layout: { visibility: 'none' }, paint: { 'raster-saturation': -1, 'raster-contrast': -0.08, 'raster-brightness-min': 0.12, 'raster-fade-duration': 250 } });
