  const main = h('button', { class: 'main', 'aria-label': 'Liste öffnen', onclick: () => { setTab('list'); openSheet(); } }, h('b', {}, title), h('small', {}, String(n)));
  main.insertAdjacentHTML('beforeend', ICON.up);
  const fb = h('button', { class: 'fbtn', 'aria-label': 'Angebote filtern', onclick: () => { setTab('cats'); openSheet(); } }, S.cats.size ? h('em', {}, String(S.cats.size)) : null);
  fb.insertAdjacentHTML('afterbegin', ICON.filter); fb.append('Angebote');
  p.append(main, fb);
