  adm.append(h('div', { class: 'win' },
    h('header', {}, h('h2', {}, 'Verwaltung'), h('span', { class: 'mode' + (Store.mode === 'sharepoint' ? ' sp' : '') }, Store.mode === 'sharepoint' ? 'SharePoint verbunden' : 'Lokaler Testmodus'),
      h('button', { class: 'x', 'aria-label': 'Schließen', html: ICON.x, onclick: closeAdmin })),
    h('div', { class: 'tabs', role: 'tablist' }, tab('loc', 'Standorte'), tab('look', 'Darstellung'), tab('map', 'Basiskarte'), tab('sp', 'SharePoint')), body));
  if (admTab === 'loc') editing ? admForm(body) : admList(body);
