    save.disabled = true; say('Wird gespeichert …');
    const prev = S.locs.slice(); let rec = S.locs.find(l => l.id === e.id);
    if (rec) Object.assign(rec, e, { demo: false }); else { rec = Object.assign({}, e, { id: 'loc-' + Date.now().toString(36) }); S.locs.push(rec); }
    delete rec.demo;
